-- Set the Category Id based on the old category values
UPDATE [dbo].[TempRates] 
SET CategoryId = 		    
    CASE [Category]
			   WHEN 'DIRECT LABOR' THEN 1
			   WHEN 'FCCOM' THEN 2
			   WHEN 'FRINGE' THEN 3
			   WHEN 'CORE G&A' THEN 4
			   WHEN 'SERVICES G&A' THEN 4
		       WHEN 'ESCALATNC' THEN 7
		       WHEN 'ESCALATNA' THEN 8
			   WHEN 'OVERHEAD' THEN 9
			   WHEN 'SM CONV' THEN 10
			   WHEN 'SVC CTR' THEN 11
			   WHEN 'Travel Fee' THEN 12
			   WHEN 'Travel Mlge' THEN 13
			   WHEN 'Travel OTC' THEN 14
			   WHEN 'Travel RC' THEN 15
			END;

UPDATE [dbo].[TempRates] 
SET CategoryId = 6
WHERE RateCode IN ('SALRYESC', 'HRNESESC');		    

GO

